with RecursiveDailyPosts as (
    select
        p.Id as PostId,
        p.OwnerUserId,
        p.CreationDate::date as CreationDay,
        p.PostTypeId,
        Coalesce(u.DisplayName, 'Unknown User') as OwnerDisplayName,
        row_number() over (partition by p.OwnerUserId, p.CreationDate::date order by p.Score desc, p.Id) as DailyRank,
        amino.GeneratedTraitMask.ud…
from Posts p
    left join Users u on p.OwnerUserId = u.Id
where p.CreationDate >= current_date - interval '30 days'
